import { randomUUID } from 'node:crypto';
import { Logger, ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import type { NestExpressApplication } from '@nestjs/platform-express';
import cookieParser from 'cookie-parser';
import type { NextFunction, Request, Response } from 'express';
import { AppModule } from './app.module';
import { HttpExceptionFilter } from './common/filters/http-exception.filter';

// Make BigInt JSON-serializable. The accumulatedReadSeconds column is BigInt
// and the default JSON serializer throws on it. Also surface a warning if a
// value would silently lose precision crossing the Number.MAX_SAFE_INTEGER
// boundary — for accumulatedReadSeconds (in seconds), the bound is hundreds
// of millions of years of total reading, so the warn should never fire in
// real data; if it does we want to know rather than silently truncate.
// Audit M-08.
const SAFE_MAX_BIGINT = BigInt(Number.MAX_SAFE_INTEGER);
(BigInt.prototype as unknown as { toJSON: () => number }).toJSON = function (
  this: bigint,
) {
  if (this > SAFE_MAX_BIGINT || this < -SAFE_MAX_BIGINT) {
    // Plain console because the NestJS Logger isn't bootstrapped yet
    // when this prototype patch is installed.
    // eslint-disable-next-line no-console
    console.warn(
      `[BigIntSerializer] value ${this.toString()} exceeds MAX_SAFE_INTEGER; precision lost`,
    );
  }
  return Number(this);
};

async function bootstrap() {
  const app = await NestFactory.create<NestExpressApplication>(AppModule);

  // Trust one reverse-proxy hop. The deploy runs Nginx (or aaPanel's
  // proxy) in front of the Node process, so the real client IP sits
  // in the X-Forwarded-For header. Without this Express reports
  // req.ip as the proxy's loopback address, which would collapse
  // per-IP rate limits into a single shared bucket. Setting it to
  // `1` (rather than `true`) is the safer flavor — it only honors
  // the leftmost XFF hop, so a malicious client appending fake XFF
  // entries to a direct backend hit (if that's reachable) can't
  // spoof their IP.
  app.set('trust proxy', 1);

  // Strip Express's default `X-Powered-By: Express` header. It
  // reveals the underlying HTTP framework, which combined with the
  // backend's NestJS error format would let an attacker pin
  // versions and look up CVEs. Audit H-05.
  app.getHttpAdapter().getInstance().disable('x-powered-by');

  // Minimum security header on every API response. Frontend already
  // sets this for HTML responses via next.config.ts; the backend's
  // JSON responses get the equivalent here so a misconfigured proxy
  // or client doesn't get a chance to MIME-sniff a JSON body into
  // an executable context. Audit L-05.
  app.use((_req: Request, res: Response, next: NextFunction) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    next();
  });

  // Per-request correlation ID. Either honor the incoming
  // X-Request-Id (set by Cloudflare / a reverse proxy that already
  // generates one) or mint a fresh UUID. Echo it back on the response
  // so a client crash report and a server log line can be matched
  // up. Audit L-07.
  app.use((req: Request, res: Response, next: NextFunction) => {
    const incoming = req.get('x-request-id');
    const id = incoming && incoming.length > 0 ? incoming : randomUUID();
    (req as Request & { id?: string }).id = id;
    res.setHeader('X-Request-Id', id);
    next();
  });

  app.setGlobalPrefix('api');

  // Cookie-parser is needed for the user-auth flow — the user JWT
  // lives in an httpOnly cookie so XSS can't read it. Admin auth is
  // unaffected (it still uses the Authorization: Bearer header).
  app.use(cookieParser());

  // Sanitize the framework-fingerprinting "Cannot GET /path" 404
  // body — see HttpExceptionFilter. Audit M-09.
  app.useGlobalFilters(new HttpExceptionFilter());

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  // Comma-separated allowlist so the same backend can serve both the
  // bare domain and a www subdomain (or a staging URL) without
  // toggling FRONTEND_URL. When the frontend lives on the same
  // domain behind Nginx, CORS is moot — but keeping it explicit
  // makes the intent obvious in a crash report.
  const origins = (process.env.FRONTEND_URL ?? 'http://localhost:3000')
    .split(',')
    .map((o) => o.trim())
    .filter(Boolean);
  app.enableCors({
    origin: origins.length === 1 ? origins[0] : origins,
    credentials: true,
  });

  const port = Number(process.env.PORT ?? 3001);
  // Bind to all interfaces so a reverse proxy on the same host (Nginx,
  // aaPanel, Caddy, etc.) can reach the API on 127.0.0.1.
  await app.listen(port, '0.0.0.0');
  // Use the NestJS Logger instead of a bare console.log — the audit
  // (L-03) flagged the latter as a non-structured emit that can't
  // be silenced in tests or routed through the same log shipper.
  new Logger('Bootstrap').log(`API running on port ${port}/api`);
}

void bootstrap();
