import { Module } from '@nestjs/common';
import { APP_INTERCEPTOR } from '@nestjs/core';
import { ConfigModule } from '@nestjs/config';
import { ThrottlerModule } from '@nestjs/throttler';
import { AuthModule } from './auth/auth.module';
import { AdminAuditInterceptor } from './common/interceptors/admin-audit.interceptor';
import { ChaptersModule } from './chapters/chapters.module';
import { CleanupModule } from './cleanup/cleanup.module';
import { FollowsModule } from './follows/follows.module';
import { HealthModule } from './health/health.module';
import { HomepageModule } from './homepage/homepage.module';
import { LikesModule } from './likes/likes.module';
import { PrismaModule } from './prisma/prisma.module';
import { ReadSessionsModule } from './read-sessions/read-sessions.module';
import { ReadingPositionsModule } from './reading-positions/reading-positions.module';
import { RecommendationsModule } from './recommendations/recommendations.module';
import { SavesModule } from './saves/saves.module';
import { SeriesModule } from './series/series.module';
import { StatsModule } from './stats/stats.module';
import { StoriesModule } from './stories/stories.module';
import { TagsModule } from './tags/tags.module';
import { UsersModule } from './users/users.module';

@Module({
  imports: [
    ConfigModule.forRoot({ isGlobal: true }),
    // Provides the default ttl/limit @Throttle() reads when callers
    // don't override. ThrottlerGuard is NOT registered globally —
    // it's only applied per-controller (currently just the auth
    // endpoints) so non-auth traffic (browsing, search, etc.)
    // isn't rate-limited under a per-IP bucket that would
    // otherwise be dominated by the Next.js SSR server's IP.
    ThrottlerModule.forRoot([{ name: 'default', ttl: 60_000, limit: 60 }]),
    PrismaModule,
    AuthModule,
    UsersModule,
    TagsModule,
    StoriesModule,
    SeriesModule,
    ChaptersModule,
    HealthModule,
    HomepageModule,
    LikesModule,
    SavesModule,
    FollowsModule,
    ReadSessionsModule,
    ReadingPositionsModule,
    RecommendationsModule,
    StatsModule,
    CleanupModule,
  ],
  providers: [
    // Records one admin_audit_log row per admin-authenticated
    // mutation. Filters internally on req.user.role + HTTP method,
    // so wiring it globally is the cheapest way to cover every
    // current and future admin controller. Audit L-02.
    {
      provide: APP_INTERCEPTOR,
      useClass: AdminAuditInterceptor,
    },
  ],
})
export class AppModule {}

// ============================================================
// Prisma Schema — Lucifer's Diary
// ============================================================

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

// ============================================================
// TAGS
// ============================================================

model Tag {
  id        String   @id @default(uuid())
  name      String   @unique
  // URL-safe slug computed from the name on write. Used by the public
  // /tag/[slug] route so tag URLs don't expose UUIDs and so they
  // survive a tag rename gracefully (the slug rewrites along with
  // the name).
  slug      String   @unique
  // Marks a tag as adult/NSFW. Stories and chapters carrying any adult
  // tag get the NSFW gate before reading. Computed on the fly from this
  // flag — there is no separate isAdult column on content.
  isAdult   Boolean  @default(false) @map("is_adult")
  createdAt DateTime @default(now()) @map("created_at")

  storyTags   StoryTag[]
  seriesTags  SeriesTag[]
  chapterTags ChapterTag[]

  @@map("tags")
}

// ============================================================
// STORIES (standalone)
// ============================================================

model Story {
  id                     String                   @id @default(uuid())
  title                  String
  content                String // full text, paginated at query time
  excerpt                String
  // Optional one- or two-line passage rendered before the body in
  // italic, centered. Standard literary-fiction device — quote, verse,
  // dedication, etc.
  epigraph               String?
  estimatedReadMinutes   Int                      @map("estimated_read_minutes")
  accumulatedReadSeconds BigInt                   @default(0) @map("accumulated_read_seconds")
  likeCount              Int                      @default(0) @map("like_count")
  isAuthorsChoice        Boolean                  @default(false) @map("is_authors_choice")
  authorsNote            String?                  @map("authors_note")
  // Private scratchpad — visible only in the CMS, never returned by
  // any public reader endpoint. Plain text by intent so the writer
  // can dump ideas at typing speed without fighting toolbar UI.
  notes                  String?
  publishedAt            DateTime?                @map("published_at")
  createdAt              DateTime                 @default(now()) @map("created_at")
  updatedAt              DateTime                 @updatedAt @map("updated_at")
  // Soft-delete timestamp (audit M-07). Set when admin clicks
  // Delete; reads filter `deletedAt: null` via a Prisma middleware.
  // A scheduled cron in cleanup.service.ts hard-deletes rows whose
  // deletedAt is older than the retention window, doing the
  // polymorphic Like/Save/Session cleanup at the same time.
  deletedAt              DateTime?                @map("deleted_at")
  // Generated tsvector — Postgres-maintained, queried via $queryRaw
  // with websearch_to_tsquery; never read through the Prisma client.
  // Modeled Unsupported so migrate dev keeps it.
  searchVector           Unsupported("tsvector")? @map("search_vector")

  tags StoryTag[]

  @@index([deletedAt])
  @@map("stories")
}

// ============================================================
// SERIES
// ============================================================

model Series {
  id                     String                   @id @default(uuid())
  title                  String
  excerpt                String
  // Optional series-level preface — surfaces on the series page above
  // the chapter list. Mirrors the authors_note field already present
  // on Story and Chapter so the three content types stay aligned.
  authorsNote            String?                  @map("authors_note")
  // Reader-facing status — lets readers know whether more chapters
  // are coming. Defaults to ONGOING for new series; flipped to
  // COMPLETE once the work is finished, HIATUS for paused series.
  status                 SeriesStatus             @default(ONGOING)
  accumulatedReadSeconds BigInt                   @default(0) @map("accumulated_read_seconds")
  likeCount              Int                      @default(0) @map("like_count")
  createdAt              DateTime                 @default(now()) @map("created_at")
  updatedAt              DateTime                 @updatedAt @map("updated_at")
  // Soft-delete timestamp — see Story.deletedAt. Series remove()
  // also stamps the deletedAt on every child chapter so the
  // soft-delete cascades cleanly.
  deletedAt              DateTime?                @map("deleted_at")
  // Generated tsvector covering title + excerpt + author's note —
  // see Story.searchVector for the contract.
  searchVector           Unsupported("tsvector")? @map("search_vector")

  chapters Chapter[]
  tags     SeriesTag[]
  follows  Follow[]

  @@index([deletedAt])
  @@map("series")
}

enum SeriesStatus {
  ONGOING
  COMPLETE
  HIATUS
}

// ============================================================
// CHAPTERS
// ============================================================

model Chapter {
  id                     String                   @id @default(uuid())
  seriesId               String                   @map("series_id")
  title                  String
  content                String
  excerpt                String
  // Optional one- or two-line passage rendered before the body in
  // italic, centered. Mirrors Story.epigraph.
  epigraph               String?
  orderIndex             Int                      @map("order_index")
  estimatedReadMinutes   Int                      @map("estimated_read_minutes")
  isAuthorsChoice        Boolean                  @default(false) @map("is_authors_choice")
  authorsNote            String?                  @map("authors_note")
  // Private scratchpad — see Story.notes.
  notes                  String?
  accumulatedReadSeconds BigInt                   @default(0) @map("accumulated_read_seconds")
  likeCount              Int                      @default(0) @map("like_count")
  publishedAt            DateTime?                @map("published_at")
  createdAt              DateTime                 @default(now()) @map("created_at")
  updatedAt              DateTime                 @updatedAt @map("updated_at")
  // Soft-delete timestamp — see Story.deletedAt. Soft-deleting a
  // series cascades a deletedAt timestamp onto every chapter it
  // owns; soft-deleting an individual chapter only touches that row.
  deletedAt              DateTime?                @map("deleted_at")
  // Generated tsvector — see Story.searchVector for the contract.
  searchVector           Unsupported("tsvector")? @map("search_vector")

  series Series       @relation(fields: [seriesId], references: [id], onDelete: Cascade)
  tags   ChapterTag[]

  @@index([seriesId, orderIndex])
  @@index([deletedAt])
  @@map("chapters")
}

// ============================================================
// JUNCTION TABLES (tags)
// ============================================================

model StoryTag {
  storyId String @map("story_id")
  tagId   String @map("tag_id")

  story Story @relation(fields: [storyId], references: [id], onDelete: Cascade)
  tag   Tag   @relation(fields: [tagId], references: [id], onDelete: Cascade)

  @@id([storyId, tagId])
  @@map("story_tags")
}

model SeriesTag {
  seriesId String @map("series_id")
  tagId    String @map("tag_id")

  series Series @relation(fields: [seriesId], references: [id], onDelete: Cascade)
  tag    Tag    @relation(fields: [tagId], references: [id], onDelete: Cascade)

  @@id([seriesId, tagId])
  @@map("series_tags")
}

model ChapterTag {
  chapterId String @map("chapter_id")
  tagId     String @map("tag_id")

  chapter Chapter @relation(fields: [chapterId], references: [id], onDelete: Cascade)
  tag     Tag     @relation(fields: [tagId], references: [id], onDelete: Cascade)

  @@id([chapterId, tagId])
  @@map("chapter_tags")
}

// ============================================================
// LIKES (anonymous + user-bound)
// ============================================================
//
// content_type is either "story" or "chapter".
// content_id is the UUID of the story or chapter.
//
// Each like row is owned by EITHER an anonymous reader (sessionToken
// from localStorage) OR a logged-in user (userId), never both. A
// CHECK constraint on the table enforces this. Two partial unique
// indexes prevent the same owner from liking the same content twice
// — one for sessionToken, one for userId — and they're added in the
// migration since Prisma doesn't model partial uniques.
//
// We deliberately keep both columns rather than migrating anonymous
// likes to userId on first login, so a reader's prior likes survive
// alongside their account-bound likes.
// ============================================================

// Polymorphic — contentId references either stories.id or chapters.id depending on
// contentType. We deliberately don't model this as a foreign key in Prisma because
// a single column can't be FK-bound to two parent tables (every insert would try
// to satisfy both constraints and fail). Cleanup of orphaned likes when a story
// or chapter is deleted is handled at the service layer.
model Like {
  id           String   @id @default(uuid())
  contentType  String   @map("content_type")
  contentId    String   @map("content_id")
  sessionToken String?  @map("session_token")
  userId       String?  @map("user_id")
  createdAt    DateTime @default(now()) @map("created_at")

  user User? @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([contentType, contentId])
  @@index([userId])
  @@map("likes")
}

// ============================================================
// READ SESSIONS (anonymous time tracking)
// ============================================================
//
// When a visitor leaves a reading page the browser sends time spent.
// If time_spent_seconds >= 50% of estimated_read_minutes * 60, qualified = true.
// On qualification, accumulated_read_seconds on the story/chapter is incremented.
// Unique constraint prevents one visitor from contributing more than once per content.
// ============================================================

// ============================================================
// USERS
// ============================================================
//
// Username + password only. No email at signup, no recovery flow —
// "if you forget, you're on your own." The email column is reserved
// for an opt-in sync feature shipped in a later PR. lastActiveAt is
// bumped on authenticated requests and feeds the silent inactivity-
// deletion cron: an account whose lastActiveAt is older than
// (now - deletionPeriodDays) is dropped without warning.
// ============================================================

model User {
  id                 String    @id @default(uuid())
  username           String    @unique
  passwordHash       String    @map("password_hash")
  // Reserved for the optional-email-sync feature (later PR). Nullable
  // by design; many users may never set one. emailVerifyToken is a
  // one-shot token written when the user first sets / changes their
  // email and consumed by the verification endpoint.
  email              String?   @unique
  emailVerifiedAt    DateTime? @map("email_verified_at")
  emailVerifyToken   String?   @map("email_verify_token")
  // Reader-configurable in the settings tab. Default 1 year.
  deletionPeriodDays Int       @default(365) @map("deletion_period_days")
  lastActiveAt       DateTime  @default(now()) @map("last_active_at")
  createdAt          DateTime  @default(now()) @map("created_at")
  updatedAt          DateTime  @updatedAt @map("updated_at")

  likes        Like[]
  savedContent SavedContent[]
  follows      Follow[]

  @@index([lastActiveAt])
  @@map("users")
}

// ============================================================
// FOLLOWS (logged-in users following a series)
// ============================================================
//
// Composite primary key on (userId, seriesId) — one row per pair.
// `lastSeenAt` is bumped when the user opens their dashboard; new
// chapters published after that timestamp surface as "unread" until
// the next visit.
// ============================================================

model Follow {
  userId     String   @map("user_id")
  seriesId   String   @map("series_id")
  lastSeenAt DateTime @default(now()) @map("last_seen_at")
  createdAt  DateTime @default(now()) @map("created_at")

  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  series Series @relation(fields: [seriesId], references: [id], onDelete: Cascade)

  @@id([userId, seriesId])
  @@index([seriesId])
  @@map("follows")
}

// ============================================================
// SAVED CONTENT (logged-in users only)
// ============================================================
//
// User's bookmark list. Polymorphic — see Like for why content_id
// doesn't have parent FKs. One row per (user, content) pair: the
// unique index makes "save" idempotent.
// ============================================================

model SavedContent {
  id          String   @id @default(uuid())
  userId      String   @map("user_id")
  contentType String   @map("content_type")
  contentId   String   @map("content_id")
  createdAt   DateTime @default(now()) @map("created_at")

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([userId, contentType, contentId])
  @@index([contentType, contentId])
  @@index([userId])
  @@map("saved_content")
}

// Polymorphic — see comment on Like for why this doesn't have parent FKs.
model ReadSession {
  id               String   @id @default(uuid())
  contentType      String   @map("content_type")
  contentId        String   @map("content_id")
  sessionToken     String   @map("session_token")
  timeSpentSeconds Int      @map("time_spent_seconds")
  qualified        Boolean  @default(false)
  createdAt        DateTime @default(now()) @map("created_at")

  @@unique([contentType, contentId, sessionToken])
  @@index([contentType, contentId])
  @@map("read_sessions")
}

// ============================================================
// READING POSITIONS (continue where you left off)
// ============================================================
//
// One row per (content × reader). On scroll the frontend posts a
// scrollPercentage 0–100 plus the current pageNumber for paginated
// reads. On revisit the chapter / story page auto-scrolls to the
// stored position.
//
// `identifier` is either a `userId` (logged-in) or a `sessionToken`
// (anonymous); `identifierType` disambiguates. Mirrors the Like
// row's split between sessionToken / userId, but keeping the two
// values in a single column gives us a clean composite unique
// constraint — readers can hold at most one position per content
// regardless of where they're authenticated.
//
// Auto-purge after 180 days lives in cleanup.service.ts.
model ReadingPosition {
  id               String   @id @default(uuid())
  contentType      String   @map("content_type")
  contentId        String   @map("content_id")
  identifier       String
  identifierType   String   @map("identifier_type")
  scrollPercentage Float    @map("scroll_percentage")
  pageNumber       Int?     @map("page_number")
  lastSeenAt       DateTime @default(now()) @updatedAt @map("last_seen_at")
  createdAt        DateTime @default(now()) @map("created_at")

  @@unique([contentType, contentId, identifier, identifierType])
  @@index([identifier, identifierType, lastSeenAt(sort: Desc)])
  @@index([contentType, contentId])
  @@map("reading_positions")
}

// ============================================================
// ADMIN AUDIT LOG (audit L-02)
// ============================================================
//
// One row per admin-authenticated mutation (POST / PATCH / DELETE
// on any route that passed JwtAuthGuard). Lets us answer "what
// changed and when?" after an incident — e.g. "story 'xyz' is
// gone, who deleted it?" The interceptor that writes this lives
// at `common/interceptors/admin-audit.interceptor.ts`.
//
// `metadata` is a free-form JSON column for extra context per
// action (HTTP method, URL, response status, bulk operation
// counts). Keeping it untyped means we can add new fields in
// service code without further migrations.
model AdminAuditLog {
  id          String   @id @default(uuid())
  action      String
  entityType  String?  @map("entity_type")
  entityId    String?  @map("entity_id")
  method      String
  path        String
  statusCode  Int      @map("status_code")
  metadata    Json?
  performedAt DateTime @default(now()) @map("performed_at")

  @@index([entityType, entityId])
  @@index([performedAt])
  @@map("admin_audit_log")
}

