import {
  Body,
  Controller,
  Get,
  HttpCode,
  HttpStatus,
  Post,
  Res,
  UseGuards,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Throttle, ThrottlerGuard } from '@nestjs/throttler';
import type { Response } from 'express';
import { AuthService } from './auth.service';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { LoginDto } from './dto/login.dto';
import { ADMIN_SESSION_COOKIE } from './strategies/jwt.strategy';

// 24h matches the JWT's expiresIn in AuthModule. The cookie can
// outlive the JWT cryptographically (it's just a string) but at
// most that means the admin sees an immediate 401 from any admin
// API call and gets redirected to /admin/login, which is fine.
const COOKIE_TTL_MS = 24 * 60 * 60 * 1000;

@Controller('auth')
export class AuthController {
  constructor(
    private readonly auth: AuthService,
    private readonly config: ConfigService,
  ) {}

  /**
   * Admin login. Validates the password, then stamps the admin JWT
   * into an httpOnly cookie instead of returning it in the response
   * body. The cookie is unreadable from JavaScript so an XSS payload
   * on the admin surface can no longer exfiltrate the token
   * (audit H-01).
   *
   * 5 attempts / minute / IP throttle stays — the rate limit
   * closes brute-force either way.
   */
  @Post('login')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 5, ttl: 60_000 } })
  async login(
    @Body() dto: LoginDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const { access_token } = await this.auth.login(dto.password);
    res.cookie(ADMIN_SESSION_COOKIE, access_token, this.cookieOptions(true));
    return { ok: true };
  }

  /**
   * Log out. Clears the admin session cookie. Idempotent — calling
   * it without a valid session still returns 204 and emits the
   * clear-cookie header, so the frontend can call it defensively.
   */
  @Post('logout')
  @HttpCode(HttpStatus.NO_CONTENT)
  logout(@Res({ passthrough: true }) res: Response) {
    res.clearCookie(ADMIN_SESSION_COOKIE, this.cookieOptions(false));
  }

  /**
   * Session probe — returns 200 if the admin cookie is present and
   * carries a valid `role: 'admin'` JWT, 401 otherwise. The frontend
   * uses this to bootstrap the "are we still logged in?" check
   * without having to call a real admin endpoint and interpret a 401.
   */
  @Get('me')
  @UseGuards(JwtAuthGuard)
  me() {
    return { ok: true };
  }

  private cookieOptions(withMaxAge: boolean) {
    const isProd = this.config.get<string>('NODE_ENV') === 'production';
    return {
      httpOnly: true,
      secure: isProd,
      // SameSite=Strict — the admin surface has no legitimate cross-
      // origin entry path (no email-link flow, no third-party
      // referrer), so the strongest CSRF mode is the right one.
      // Mirrors the user-jwt cookie tightened in audit H-03.
      sameSite: 'strict' as const,
      path: '/',
      ...(withMaxAge ? { maxAge: COOKIE_TTL_MS } : {}),
    };
  }
}
