import {
  Body,
  Controller,
  Get,
  HttpCode,
  HttpStatus,
  NotFoundException,
  Patch,
  Post,
  Res,
  UseGuards,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Throttle, ThrottlerGuard } from '@nestjs/throttler';
import type { Response } from 'express';
import { CurrentUser } from './decorators/current-user.decorator';
import type { AuthenticatedUser } from './decorators/current-user.decorator';
import { ChangePasswordDto } from './dto/change-password.dto';
import { SignupDto } from './dto/signup.dto';
import { UpdateSettingsDto } from './dto/update-settings.dto';
import { UserLoginDto } from './dto/login.dto';
import { UserJwtAuthGuard } from './guards/user-jwt-auth.guard';
import { USER_SESSION_COOKIE } from './strategies/user-jwt.strategy';
import { UsersService } from './users.service';

// 30 days. The session is meant to feel persistent — the reader
// doesn't have an email to recover with, so kicking them out
// frequently would be hostile. The JWT itself expires at the same
// horizon (set in UsersModule.JwtModule.signOptions).
const SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * Public account endpoints. /signup and /login are unauthenticated
 * (they'd be quite useless otherwise); /me and /logout require the
 * user-jwt cookie set by the first two.
 */
@Controller('users')
export class UsersController {
  constructor(
    private readonly users: UsersService,
    private readonly config: ConfigService,
  ) {}

  /**
   * Signup: 3 / minute / IP. Tighter than login because signup
   * creates a permanent resource (a user row) and is a normally
   * once-in-a-lifetime action — abuse looks like an attacker
   * grinding throwaway accounts, not a legitimate fat-finger.
   */
  @Post('signup')
  @HttpCode(HttpStatus.CREATED)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 3, ttl: 60_000 } })
  async signup(
    @Body() dto: SignupDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.users.signup(dto);
    this.setSessionCookie(res, result.access_token);
    return { user: result.user };
  }

  /**
   * Login: 5 / minute / IP — same shape as admin login. A wrong
   * password gets the user 5 retries before the next attempt 429s.
   */
  @Post('login')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 5, ttl: 60_000 } })
  async login(
    @Body() dto: UserLoginDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.users.login(dto);
    this.setSessionCookie(res, result.access_token);
    return { user: result.user };
  }

  @Post('logout')
  @HttpCode(HttpStatus.NO_CONTENT)
  logout(@Res({ passthrough: true }) res: Response) {
    res.clearCookie(USER_SESSION_COOKIE, this.cookieOptions());
  }

  @Get('me')
  @UseGuards(UserJwtAuthGuard)
  async me(@CurrentUser() user: AuthenticatedUser) {
    const fresh = await this.users.findById(user.id);
    if (!fresh) throw new NotFoundException();
    // Bump activity. Fire-and-forget inside the service.
    this.users.touchLastActive(user.id);
    return { user: fresh };
  }

  @Patch('me')
  @UseGuards(UserJwtAuthGuard)
  async updateSettings(
    @Body() dto: UpdateSettingsDto,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    const updated = await this.users.updateSettings(user.id, dto);
    return { user: updated };
  }

  @Patch('me/password')
  @HttpCode(HttpStatus.NO_CONTENT)
  @UseGuards(UserJwtAuthGuard)
  async changePassword(
    @Body() dto: ChangePasswordDto,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    await this.users.changePassword(user.id, dto);
  }

  private setSessionCookie(res: Response, token: string) {
    res.cookie(USER_SESSION_COOKIE, token, {
      ...this.cookieOptions(),
      maxAge: SESSION_TTL_MS,
    });
  }

  private cookieOptions() {
    const isProd = this.config.get<string>('NODE_ENV') === 'production';
    return {
      httpOnly: true,
      // sameSite=strict — strongest CSRF protection. Modern Chrome
      // already blocks cross-origin POSTs with Lax, but Strict
      // closes the residual edges (older browsers, the brief
      // navigation-timing window some Lax implementations
      // honored). The UX trade-off — typing /profile in a new tab's
      // address bar doesn't send the cookie on that one request —
      // is acceptable here: every public route reads fine without
      // the cookie, and once the user is back in same-origin
      // navigation context the cookie flows normally. Audit H-03.
      sameSite: 'strict' as const,
      secure: isProd,
      path: '/',
    };
  }
}
