import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Query,
  Post,
  Req,
  UseGuards,
} from '@nestjs/common';
import { Throttle } from '@nestjs/throttler';
import type { Request } from 'express';
import { UserThrottlerGuard } from '../common/guards/user-throttler.guard';
import { CurrentUser } from '../users/decorators/current-user.decorator';
import type { AuthenticatedUser } from '../users/decorators/current-user.decorator';
import { OptionalUserJwtAuthGuard } from '../users/guards/optional-user-jwt-auth.guard';
import { UserJwtAuthGuard } from '../users/guards/user-jwt-auth.guard';
import { LikeDto } from './dto/like.dto';
import type { LikeActor } from './likes.service';
import { LikesService } from './likes.service';

@Controller('likes')
export class LikesController {
  constructor(private readonly likes: LikesService) {}

  // Reuses LikeDto for query-string validation — same shape, same
  // rules. Without this, `contentType` and `contentId` came in as
  // raw strings and any garbage value reached the service before
  // Prisma threw a confusing downstream error instead of a clean 400.
  @Get('status')
  @UseGuards(OptionalUserJwtAuthGuard)
  getStatus(
    @Query() query: LikeDto,
    @Req() req: Request & { user?: AuthenticatedUser | null },
  ) {
    const actor = this.resolveActor(req.user ?? null, query.sessionToken);
    return this.likes.getStatus(query.contentType, query.contentId, actor);
  }

  // 20 mutations / minute / actor. Generous enough for a real reader
  // (you'd have to like 21 different things in a single minute to
  // hit this) but tight enough that an automated bot can't grind
  // tens of thousands of like rows per hour. Audit M-03.
  @Post()
  @HttpCode(HttpStatus.OK)
  @UseGuards(OptionalUserJwtAuthGuard, UserThrottlerGuard)
  @Throttle({ default: { limit: 20, ttl: 60_000 } })
  like(
    @Body() dto: LikeDto,
    @Req() req: Request & { user?: AuthenticatedUser | null },
  ) {
    const actor = this.resolveActor(req.user ?? null, dto.sessionToken);
    return this.likes.like(dto.contentType, dto.contentId, actor);
  }

  @Delete()
  @HttpCode(HttpStatus.OK)
  @UseGuards(OptionalUserJwtAuthGuard, UserThrottlerGuard)
  @Throttle({ default: { limit: 20, ttl: 60_000 } })
  unlike(
    @Body() dto: LikeDto,
    @Req() req: Request & { user?: AuthenticatedUser | null },
  ) {
    const actor = this.resolveActor(req.user ?? null, dto.sessionToken);
    return this.likes.unlike(dto.contentType, dto.contentId, actor);
  }

  /**
   * Rich list for the dashboard "Liked" tab. The frontend passes
   * its anonymous sessionToken (if any) so likes from before the
   * account existed are included in the result.
   */
  @Get('me')
  @UseGuards(UserJwtAuthGuard)
  listMine(
    @CurrentUser() user: AuthenticatedUser,
    @Query('sessionToken') sessionToken?: string,
  ) {
    return this.likes.listForUserWithCards(user.id, sessionToken);
  }

  /**
   * Compact `contentType:contentId` keys the user has liked. Used
   * to hydrate LikeButton state for many cards in one go without
   * polling /status per card.
   */
  @Get('me/ids')
  @UseGuards(UserJwtAuthGuard)
  async listMineIds(
    @CurrentUser() user: AuthenticatedUser,
    @Query('sessionToken') sessionToken?: string,
  ) {
    const ids = await this.likes.listIdsForUser(user.id, sessionToken);
    return { ids };
  }

  /**
   * Decides whether the request is acting as a user or as an
   * anonymous reader. Logged-in users may *also* pass a sessionToken
   * — when they do, the anonymous token is included in lookups so a
   * pre-signup like still reads as "liked" for them.
   */
  private resolveActor(
    user: AuthenticatedUser | null,
    sessionToken: string | undefined,
  ): LikeActor {
    if (user) {
      return { kind: 'user', userId: user.id, sessionToken };
    }
    if (!sessionToken) {
      throw new BadRequestException(
        'sessionToken is required when not signed in',
      );
    }
    return { kind: 'anonymous', sessionToken };
  }
}
