} from '@nestjs/common';
import { Throttle } from '@nestjs/throttler';
import { UserThrottlerGuard } from '../common/guards/user-throttler.guard';
import { CurrentUser } from '../users/decorators/current-user.decorator';
import type { AuthenticatedUser } from '../users/decorators/current-user.decorator';
import { UserJwtAuthGuard } from '../users/guards/user-jwt-auth.guard';
import type { ContentType } from './dto/save.dto';
import { SaveDto } from './dto/save.dto';
import { SavesService } from './saves.service';

/**
 * Save / unsave endpoints. All require a logged-in user — anonymous
 * "save" doesn't exist; we point the reader at /signup instead. The
 * "is this saved" status returns false for unauthenticated callers
 * (handled at the guard level: 401 → SaveButton renders disabled).
 */
@Controller('saves')
@UseGuards(UserJwtAuthGuard)
export class SavesController {
  constructor(private readonly saves: SavesService) {}

  @Get('status')
  getStatus(
    @Query('contentType') contentType: ContentType,
    @Query('contentId') contentId: string,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    return this.saves.getStatus(user.id, contentType, contentId);
  }

  // Audit M-03: 20 save mutations / minute / user.
  @Post()
  @HttpCode(HttpStatus.OK)
  @UseGuards(UserThrottlerGuard)
  @Throttle({ default: { limit: 20, ttl: 60_000 } })
  save(@Body() dto: SaveDto, @CurrentUser() user: AuthenticatedUser) {
    return this.saves.save(user.id, dto.contentType, dto.contentId);
  }

  @Delete()
  @HttpCode(HttpStatus.OK)
  @UseGuards(UserThrottlerGuard)
  @Throttle({ default: { limit: 20, ttl: 60_000 } })
  unsave(@Body() dto: SaveDto, @CurrentUser() user: AuthenticatedUser) {
    return this.saves.unsave(user.id, dto.contentType, dto.contentId);
  }

  /**
   * The dashboard's "Saved" tab. Returns rich card rows so the
   * frontend can render them without a follow-up batch request.
   */
  @Get('me')
  listMine(@CurrentUser() user: AuthenticatedUser) {
    return this.saves.listForUser(user.id);
  }

  /**
   * Compact list of `contentType:contentId` strings the user has
   * saved. The SaveButton uses it to decide its initial pressed
   * state for any content the page knows about (cards, etc.) without
   * one HTTP call per button.
   */
  @Get('me/ids')
  async listMineIds(@CurrentUser() user: AuthenticatedUser) {
    const ids = await this.saves.listIdsForUser(user.id);
    return { ids };
  }
}
