import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Query,
  Req,
  UseGuards,
} from '@nestjs/common';
import { Throttle } from '@nestjs/throttler';
import type { Request } from 'express';
import { UserThrottlerGuard } from '../common/guards/user-throttler.guard';
import type { AuthenticatedUser } from '../users/decorators/current-user.decorator';
import { OptionalUserJwtAuthGuard } from '../users/guards/optional-user-jwt-auth.guard';
import { QueryByContentDto } from './dto/query-by-content.dto';
import { UpsertPositionDto } from './dto/upsert-position.dto';
import type { ContentType } from './dto/upsert-position.dto';
import type { PositionActor } from './reading-positions.service';
import { ReadingPositionsService } from './reading-positions.service';

const VALID_CONTENT_TYPES: readonly ContentType[] = ['story', 'chapter'];

@Controller('reading-positions')
export class ReadingPositionsController {
  constructor(private readonly positions: ReadingPositionsService) {}

  /**
   * Upsert the caller's position for a piece of content. The frontend
   * calls this on a 5-second scroll throttle + on visibility-hidden
   * via sendBeacon so the latest position is captured even when the
   * tab closes mid-scroll.
   *
   * Rate-limited at 60 writes/min/actor — generous enough that a real
   * reader scrolling continuously won't hit it (60s / 5s = 12 writes
   * is the steady-state load), tight enough that a stuck client or a
   * bot can't grind out millions of rows.
   */
  @Post()
  @HttpCode(HttpStatus.OK)
  @UseGuards(OptionalUserJwtAuthGuard, UserThrottlerGuard)
  @Throttle({ default: { limit: 60, ttl: 60_000 } })
  upsert(
    @Body() dto: UpsertPositionDto,
    @Req() req: Request & { user?: AuthenticatedUser | null },
  ) {
    const actor = this.resolveActor(req.user ?? null, dto.sessionToken);
    return this.positions.upsert(
      actor,
      dto.contentType,
      dto.contentId,
      dto.scrollPercentage,
      dto.pageNumber ?? null,
    );
  }

  /**
   * Last 10 positions for the caller, joined to live content cards.
   * Powers the homepage "Continue reading" row.
   */
  @Get('continue')
  @UseGuards(OptionalUserJwtAuthGuard)
  continue(
    @Req() req: Request & { user?: AuthenticatedUser | null },
    @Query('sessionToken') sessionToken?: string,
  ) {
    const actor = this.resolveActor(req.user ?? null, sessionToken);
    return this.positions.continue(actor);
  }

  /**
   * Single-row lookup used by `useReadingPosition` on chapter / story
   * mount. Returns `null` (not 404) when no position exists so the
   * hook can no-op without parsing an error code.
   */
  @Get('by-content')
  @UseGuards(OptionalUserJwtAuthGuard)
  byContent(
    @Query() query: QueryByContentDto,
    @Req() req: Request & { user?: AuthenticatedUser | null },
  ) {
    const actor = this.resolveActor(req.user ?? null, query.sessionToken);
    return this.positions.getOne(actor, query.contentType, query.contentId);
  }

  /**
   * Remove the caller's position for a piece of content — the X
   * button on a ContinueCard. Idempotent: no row → still 200.
   */
  @Delete(':contentType/:contentId')
  @HttpCode(HttpStatus.OK)
  @UseGuards(OptionalUserJwtAuthGuard, UserThrottlerGuard)
  @Throttle({ default: { limit: 60, ttl: 60_000 } })
  remove(
    @Param('contentType') contentType: string,
    @Param('contentId') contentId: string,
    @Req() req: Request & { user?: AuthenticatedUser | null },
    @Query('sessionToken') sessionToken?: string,
  ) {
    if (!VALID_CONTENT_TYPES.includes(contentType as ContentType)) {
      throw new BadRequestException(
        `contentType must be one of: ${VALID_CONTENT_TYPES.join(', ')}`,
      );
    }
    // Light UUID-shape guard — Prisma would also throw, but a clean
    // 400 reads better than a P2023 surfacing as a 500. Format-only:
    // we don't care whether the row exists, deleteMany handles that.
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(contentId)) {
      throw new BadRequestException('contentId must be a UUID');
    }
    const actor = this.resolveActor(req.user ?? null, sessionToken);
    return this.positions.remove(actor, contentType as ContentType, contentId);
  }

  /**
   * Decides whether the request acts as a user or as an anonymous
   * session. Mirrors the same shape as likes / saves so the rate of
   * cross-module confusion is low. Anonymous calls without a session
   * token are 400 rather than silently dropped — the hook always
   * sends one, so a missing value is a frontend bug worth surfacing.
   */
  private resolveActor(
    user: AuthenticatedUser | null,
    sessionToken: string | undefined,
  ): PositionActor {
    if (user) return { kind: 'user', userId: user.id };
    if (!sessionToken) {
      throw new BadRequestException(
        'sessionToken is required when not signed in',
      );
    }
    return { kind: 'session', sessionToken };
  }
}
