import { Controller, Get } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Controller('health')
export class HealthController {
  constructor(private readonly prisma: PrismaService) {}

  /**
   * Liveness probe — answers as long as the Node process is up. Used
   * by hosting platforms (Render, Fly, Railway, etc.) and the docker
   * compose healthcheck. Cheap; no DB call.
   *
   * Intentionally minimal payload: just `{ status: 'ok' }`. The
   * previous version also returned `process.uptime()`, which the
   * security audit flagged (M-05) as a fingerprinting signal —
   * unauthenticated callers could deduce deploy cadence and the
   * existence of a separate Node process. Probes don't need it.
   */
  @Get()
  liveness() {
    return { status: 'ok' };
  }

  /**
   * Readiness probe — only returns ok when the DB is reachable. Used
   * by deploy gates that need to know if the API can actually serve
   * traffic (vs. being booted but disconnected).
   */
  @Get('ready')
  async readiness() {
    try {
      await this.prisma.$queryRaw`SELECT 1`;
      return { status: 'ok' };
    } catch {
      return { status: 'degraded', database: 'unreachable' };
    }
  }
}

