  imports: [
    PassportModule,
    JwtModule.registerAsync({
      inject: [ConfigService],
      useFactory: (config: ConfigService) => ({
        secret: config.getOrThrow<string>('JWT_SECRET'),
        // Admin tokens live for 24h, not 7d, so a leaked Bearer token
        // has a one-day blast radius instead of a one-week one. The
        // CMS sees light traffic — a daily re-auth is acceptable UX
        // friction for the privileged surface. User-side JWTs in
        // UsersModule keep the longer 30d window because those are
        // convenience tokens, not privileged ones.
        signOptions: { expiresIn: '24h' },
      }),
    }),
  ],
  controllers: [AuthController],
  providers: [AuthService, JwtStrategy],
  exports: [JwtStrategy, PassportModule, JwtModule],
})
