import { Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy } from 'passport-jwt';
import type { Request } from 'express';
import type { JwtPayload } from '../auth.service';

// Shared between this strategy (reads it) and the controller (writes
// it via Set-Cookie). Lives at this module's strategy file so other
// modules importing it stay decoupled from the controller.
export const ADMIN_SESSION_COOKIE = 'lucifer_admin_session';

/**
 * Admin JWT strategy. Reads the token from the httpOnly
 * `lucifer_admin_session` cookie and only accepts tokens carrying
 * `role: 'admin'`.
 *
 * Previously the token was extracted from the `Authorization: Bearer`
 * header — which works, but pushed the frontend to keep the token
 * in `localStorage`, where any XSS payload could read it and pivot
 * to a full CMS takeover (audit H-01). Cookies marked httpOnly are
 * unreadable from JavaScript, so the same XSS no longer leads to
 * an admin token leak. The migration is mirrored in the user
 * strategy file next door.
 */
@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(config: ConfigService) {
    super({
      jwtFromRequest: (req: Request) => {
        const cookies = (req as Request & { cookies?: Record<string, string> })
          .cookies;
        return cookies?.[ADMIN_SESSION_COOKIE] ?? null;
      },
      ignoreExpiration: false,
      secretOrKey: config.getOrThrow<string>('JWT_SECRET'),
    });
  }

  validate(payload: JwtPayload) {
    if (payload.role !== 'admin') {
      throw new UnauthorizedException();
    }
    return { role: payload.role };
  }
}
