import { Module } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JwtModule } from '@nestjs/jwt';
import { PassportModule } from '@nestjs/passport';
import { PrismaModule } from '../prisma/prisma.module';
import { UserJwtStrategy } from './strategies/user-jwt.strategy';
import { UsersController } from './users.controller';
import { UsersService } from './users.service';

/**
 * Public-side accounts. Lives separately from AuthModule (which is
 * admin-only) so the two auth domains don't share guards or
 * lifetimes. Both modules sign with the same JWT_SECRET — strategies
 * differentiate by transport (cookie vs Bearer) and by the `role`
 * claim each one validates.
 */
@Module({
  imports: [
    PrismaModule,
    PassportModule,
    JwtModule.registerAsync({
      inject: [ConfigService],
      useFactory: (config: ConfigService) => ({
        secret: config.getOrThrow<string>('JWT_SECRET'),
        // Match the cookie maxAge in UsersController. JWT expiry is
        // belt-and-suspenders alongside the cookie TTL — if either
        // expires, the session is dead.
        signOptions: { expiresIn: '30d' },
      }),
    }),
  ],
  controllers: [UsersController],
  providers: [UsersService, UserJwtStrategy],
  exports: [UsersService, UserJwtStrategy, PassportModule],
})
export class UsersModule {}
