import { Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy } from 'passport-jwt';
import type { Request } from 'express';
import type { UserJwtPayload } from '../users.service';

export const USER_SESSION_COOKIE = 'lucifer_user_session';

/**
 * User JWT strategy. Reads the token from the httpOnly
 * `lucifer_user_session` cookie and only accepts tokens carrying
 * `role: 'user'`. Lives in a separate strategy from the admin one
 * so the two auth domains can't accidentally accept each other's
 * tokens.
 */
@Injectable()
export class UserJwtStrategy extends PassportStrategy(Strategy, 'user-jwt') {
  constructor(config: ConfigService) {
    super({
      jwtFromRequest: (req: Request) => {
        const cookies = (req as Request & { cookies?: Record<string, string> })
          .cookies;
        return cookies?.[USER_SESSION_COOKIE] ?? null;
      },
      ignoreExpiration: false,
      secretOrKey: config.getOrThrow<string>('JWT_SECRET'),
    });
  }

  validate(payload: UserJwtPayload) {
    if (payload.role !== 'user') {
      throw new UnauthorizedException();
    }
    return { id: payload.sub, username: payload.username, role: payload.role };
  }
}
