import { ExecutionContext, Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

/**
 * Same passport strategy as UserJwtAuthGuard but tolerates a missing
 * or invalid cookie. Used on endpoints that have a logged-in flavor
 * and an anonymous flavor — like /api/likes — so the controller can
 * branch on req.user being present without 401-ing the anonymous
 * caller.
 */
@Injectable()
export class OptionalUserJwtAuthGuard extends AuthGuard('user-jwt') {
  // Force the strategy to run even if no auth header / cookie is
  // present. Default behavior would short-circuit and never invoke
  // handleRequest.
  async canActivate(context: ExecutionContext): Promise<boolean> {
    try {
      await super.canActivate(context);
    } catch {
      // swallow — handleRequest below decides what to do
    }
    return true;
  }

  handleRequest<T>(_err: unknown, user: T | false): T | null {
    // Return null instead of throwing so a missing or expired cookie
    // simply leaves req.user undefined.
    return user || null;
  }
}
