import { Injectable } from '@nestjs/common';
import { ThrottlerGuard } from '@nestjs/throttler';

/**
 * Throttle by authenticated user id when present, otherwise by IP.
 *
 * Used on user-interaction endpoints (likes, saves, follows). These
 * routes accept both anonymous (sessionToken-only) and authenticated
 * callers in some cases — likes for example. Per-IP throttling alone
 * would conflate every user behind a shared NAT into one bucket and
 * either be too generous (large bucket) or too tight (small bucket
 * shared across real users). Per-user (when known) is the right
 * unit; IP fallback covers the still-anonymous case.
 *
 * Auth-required routes carry `req.user` by the time this guard runs
 * because UserJwtAuthGuard is applied at the controller class level
 * — class-level guards execute before method-level ones, so `user`
 * is populated when we reach here.
 */
@Injectable()
export class UserThrottlerGuard extends ThrottlerGuard {
  protected getTracker(
    req: Record<string, unknown> & { user?: { id?: string }; ip?: string },
  ): Promise<string> {
    const userId = req.user?.id;
    if (typeof userId === 'string' && userId.length > 0) return Promise.resolve(`user:${userId}`);
    return Promise.resolve(`ip:${req.ip ?? 'unknown'}`);
  }
}

