import { Injectable, Logger } from '@nestjs/common';
import { Cron } from '@nestjs/schedule';
import { PrismaService } from '../prisma/prisma.service';

// Retention window for soft-deleted content (audit M-07). Admins can
// restore within this window by clearing `deleted_at` in the DB.
// Older than this and the cron purges the row plus its polymorphic
// Like / SavedContent / ReadSession / ReadingPosition rows.
const SOFT_DELETE_RETENTION_DAYS = 30;

// Retention window for "continue reading" positions. Anything older
// than this stops looking like a position the reader actively cares
// about — surfacing six-month-old half-reads in the dashboard is
// more annoying than helpful. When the row is gone the hook just
// no-ops on next visit, which is the natural fallback.
const READING_POSITION_RETENTION_DAYS = 180;

/**
 * Daily cleanup cron. Three jobs in one task:
 *
 *   1. Inactive accounts — each user picks their own deletion period
 *      (30-3650 days) in settings. Accounts whose lastActiveAt is
 *      older than (now - deletionPeriodDays) are dropped. FK
 *      cascades take the user's related rows along.
 *
 *   2. Soft-deleted content — stories / chapters / series whose
 *      `deletedAt` was stamped more than SOFT_DELETE_RETENTION_DAYS
 *      ago. Hard-deletes the row AND its polymorphic Like /
 *      ReadSession / SavedContent / ReadingPosition rows. Audit M-07.
 *
 *   3. Stale reading positions — rows in `reading_positions` whose
 *      `last_seen_at` is older than READING_POSITION_RETENTION_DAYS.
 *
 * Runs at 03:15 server-local time — off-peak.
 */
@Injectable()
export class CleanupService {
  private readonly logger = new Logger(CleanupService.name);

  constructor(private readonly prisma: PrismaService) {}

  @Cron('15 3 * * *', { name: 'daily-cleanup' })
  async runDailyCleanup() {
    const accounts = await this.deleteInactiveAccounts();
    if (accounts > 0) {
      this.logger.log(`Inactivity cron deleted ${accounts} account(s)`);
    }

    const purged = await this.purgeSoftDeletedContent();
    if (purged.total > 0) {
      this.logger.log(
        `Soft-delete cron purged ${purged.stories} story / ${purged.chapters} chapter / ${purged.series} series row(s) plus polymorphic refs`,
      );
    }

    const stalePositions = await this.purgeStaleReadingPositions();
    if (stalePositions > 0) {
      this.logger.log(
        `Reading-position cron purged ${stalePositions} stale row(s)`,
      );
    }
  }

  /**
   * Account-inactivity cleanup. Each user's row carries its own
   * threshold (`deletion_period_days`), so a single SQL statement
   * is cheaper than a Prisma findMany + delete loop and atomic.
   */
  async deleteInactiveAccounts(): Promise<number> {
    return this.prisma.$executeRaw`
      DELETE FROM "users"
      WHERE "last_active_at" <
        (NOW() - ("deletion_period_days" || ' days')::interval)
    `;
  }

  /**
   * Hard-delete content soft-deleted more than the retention window
   * ago, plus the polymorphic rows pointing at it (audit M-07).
   * Returns counts per content type for observability.
   *
   * Order matters: clean Likes / Saves / Sessions BEFORE deleting
   * the content row. Otherwise the polymorphic rows would briefly
   * point at a non-existent id between the delete + cleanup, which
   * is harmless but ugly. The whole block runs inside a transaction.
   */
  async purgeSoftDeletedContent(): Promise<{
    stories: number;
    chapters: number;
    series: number;
    total: number;
  }> {
    const threshold = new Date(
      Date.now() - SOFT_DELETE_RETENTION_DAYS * 24 * 60 * 60 * 1000,
    );

    // Find the doomed rows first so we can clean polymorphic refs
    // by exact id. `deletedAt: { not: null }` bypasses the read
    // filter convention (the only intentional place that does).
    const [doomedStories, doomedChapters, doomedSeries] = await Promise.all([
      this.prisma.story.findMany({
        where: { deletedAt: { not: null, lt: threshold } },
        select: { id: true },
      }),
      this.prisma.chapter.findMany({
        where: { deletedAt: { not: null, lt: threshold } },
        select: { id: true },
      }),
      this.prisma.series.findMany({
        where: { deletedAt: { not: null, lt: threshold } },
        select: { id: true },
      }),
    ]);

    const storyIds = doomedStories.map((s) => s.id);
    const chapterIds = doomedChapters.map((c) => c.id);
    const seriesIds = doomedSeries.map((s) => s.id);

    if (
      storyIds.length === 0 &&
      chapterIds.length === 0 &&
      seriesIds.length === 0
    ) {
      return { stories: 0, chapters: 0, series: 0, total: 0 };
    }

    await this.prisma.$transaction([
      // Polymorphic rows for stories
      this.prisma.like.deleteMany({
        where: { contentType: 'story', contentId: { in: storyIds } },
      }),
      this.prisma.readSession.deleteMany({
        where: { contentType: 'story', contentId: { in: storyIds } },
      }),
      this.prisma.savedContent.deleteMany({
        where: { contentType: 'story', contentId: { in: storyIds } },
      }),
      this.prisma.readingPosition.deleteMany({
        where: { contentType: 'story', contentId: { in: storyIds } },
      }),
      // Polymorphic rows for chapters
      this.prisma.like.deleteMany({
        where: { contentType: 'chapter', contentId: { in: chapterIds } },
      }),
      this.prisma.readSession.deleteMany({
        where: { contentType: 'chapter', contentId: { in: chapterIds } },
      }),
      this.prisma.savedContent.deleteMany({
        where: { contentType: 'chapter', contentId: { in: chapterIds } },
      }),
      this.prisma.readingPosition.deleteMany({
        where: { contentType: 'chapter', contentId: { in: chapterIds } },
      }),
      // Polymorphic rows for series themselves
      this.prisma.like.deleteMany({
        where: { contentType: 'series', contentId: { in: seriesIds } },
      }),
      this.prisma.readSession.deleteMany({
        where: { contentType: 'series', contentId: { in: seriesIds } },
      }),
      this.prisma.savedContent.deleteMany({
        where: { contentType: 'series', contentId: { in: seriesIds } },
      }),
      // Hard delete the content rows. Series delete cascades any
      // remaining chapters via the FK; we already collected the
      // chapter ids before that fires.
      this.prisma.story.deleteMany({ where: { id: { in: storyIds } } }),
      this.prisma.chapter.deleteMany({ where: { id: { in: chapterIds } } }),
      this.prisma.series.deleteMany({ where: { id: { in: seriesIds } } }),
    ]);

    return {
      stories: storyIds.length,
      chapters: chapterIds.length,
      series: seriesIds.length,
      total: storyIds.length + chapterIds.length + seriesIds.length,
    };
  }

  /**
   * Drop reading-position rows older than the retention window.
   * Returns the count for the cron log. Cheap — a single bounded
   * DELETE backed by the (last_seen_at) ordering on the
   * (identifier, identifier_type, last_seen_at DESC) index.
   */
  async purgeStaleReadingPositions(): Promise<number> {
    const threshold = new Date(
      Date.now() - READING_POSITION_RETENTION_DAYS * 24 * 60 * 60 * 1000,
    );
    const result = await this.prisma.readingPosition.deleteMany({
      where: { lastSeenAt: { lt: threshold } },
    });
    return result.count;
  }
}
