import { Module } from '@nestjs/common';
import { ScheduleModule } from '@nestjs/schedule';
import { PrismaModule } from '../prisma/prisma.module';
import { CleanupService } from './cleanup.service';

/**
 * Hosts the in-process cron that silently deletes inactive
 * accounts. ScheduleModule.forRoot() boots the cron registry; the
 * @Cron decorator on CleanupService.runDailyCleanup() handles the
 * actual scheduling.
 *
 * Single-instance only — we run on PM2 with a fixed worker count,
 * so we don't need a distributed lock. If we ever scale out
 * horizontally, gate the cron on a row-level advisory lock or move
 * to an external scheduler.
 */
@Module({
  imports: [ScheduleModule.forRoot(), PrismaModule],
  providers: [CleanupService],
  exports: [CleanupService],
})
export class CleanupModule {}
