import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import type { Request, Response } from 'express';
import { Observable, tap } from 'rxjs';
import { PrismaService } from '../../prisma/prisma.service';

/**
 * Records one row in `admin_audit_log` for every mutation
 * performed by an admin-authenticated request (audit L-02).
 *
 * Only logs:
 *   - method ∈ {POST, PATCH, DELETE}
 *   - req.user.role === 'admin' (set by JwtStrategy.validate)
 *
 * Anonymous reads, public-API hits, and user-authenticated traffic
 * are skipped. The write is fire-and-forget — a log failure logs
 * to the application Logger but never blocks or fails the response.
 *
 * Registered globally via APP_INTERCEPTOR in AppModule so every
 * controller gets coverage without per-route decorators.
 */
@Injectable()
export class AdminAuditInterceptor implements NestInterceptor {
  private readonly logger = new Logger(AdminAuditInterceptor.name);

  constructor(private readonly prisma: PrismaService) {}

  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<unknown> {
    const req = context.switchToHttp().getRequest<Request>();
    const res = context.switchToHttp().getResponse<Response>();
    const method = req.method;

    if (!isAuditableMethod(method)) return next.handle();
    const user = (req as Request & { user?: { role?: string } }).user;
    if (user?.role !== 'admin') return next.handle();

    return next.handle().pipe(
      tap(() => {
        // Defer to next tick so res.statusCode has been finalized by
        // the framework before we capture it.
        const path = req.path;
        const parsed = parseAdminPath(path);
        const action = determineAction(method, path);

        // Fire-and-forget — audit logging is operational telemetry,
        // not part of the response contract.
        // `metadata` is left undefined here so the column stores
        // SQL NULL — Prisma's JSON typing rejects literal `null`.
        // Service-layer code can extend the audit later by passing
        // a concrete shape if structured per-action data is wanted.
        this.prisma.adminAuditLog
          .create({
            data: {
              action,
              entityType: parsed.entityType,
              entityId: parsed.entityId,
              method,
              path,
              statusCode: res.statusCode,
            },
          })
          .catch((err: unknown) => {
            this.logger.warn(
              `audit-log write failed for ${method} ${path}: ${
                err instanceof Error ? err.message : String(err)
              }`,
            );
          });
      }),
    );
  }
}

function isAuditableMethod(method: string): boolean {
  return method === 'POST' || method === 'PATCH' || method === 'DELETE';
}

// Parse /api/admin/stories/<id>/publish-style paths into a coarse
// entity type + id. Unknown shapes return nulls and the row still
// gets a path + method so the audit isn't blind even for routes
// the parser doesn't recognize.
function parseAdminPath(path: string): {
  entityType: string | null;
  entityId: string | null;
} {
  const stripped = path.replace(/^\/?(api\/)?admin\//, '');
  const m = /^([a-z]+)(?:\/([a-f0-9-]+))?/.exec(stripped);
  if (!m) return { entityType: null, entityId: null };
  return {
    entityType: m[1] ?? null,
    entityId: m[2] ?? null,
  };
}

function determineAction(method: string, path: string): string {
  if (method === 'DELETE') return 'delete';
  if (method === 'PATCH') return 'update';
  // POST: differentiate by URL suffix when available.
  if (path.endsWith('/publish')) return 'publish';
  if (path.endsWith('/unpublish')) return 'unpublish';
  if (path.endsWith('/bulk')) return 'bulk';
  if (path.endsWith('/reorder') || path.endsWith('/order')) return 'reorder';
  return 'create';
}
