import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
} from '@nestjs/common';
import type { Response } from 'express';

// Express's default 404 message for an unmatched route. The pattern
// is distinctive enough that the security audit flagged it as
// framework fingerprinting — replace it with a generic message
// while leaving deliberate `NotFoundException`s from controllers
// (e.g. "Story <id> not found") untouched, since their messages
// don't leak framework details.
const ROUTE_MISS_PATTERN = /^Cannot \w+ \/.*$/;

/**
 * Global HTTP exception filter.
 *
 * Only intervenes on the one error case that needs sanitizing:
 * the default Express/NestJS 404 response for an unmatched route,
 * which surfaces as `{ message: "Cannot GET /path", ... }` — a
 * known fingerprinting signal for Express. Everything else
 * (validation 400s, deliberate NotFoundExceptions with custom
 * messages, 401/403/409/etc.) flows through unchanged so the
 * frontend keeps the useful payload it relies on.
 */
@Catch(HttpException)
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: HttpException, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const status = exception.getStatus();
    const body = exception.getResponse();

    if (status === 404) {
      const message =
        typeof body === 'string'
          ? body
          : (body as { message?: unknown })?.message;
      if (typeof message === 'string' && ROUTE_MISS_PATTERN.test(message)) {
        response.status(404).json({ statusCode: 404, message: 'Not found' });
        return;
      }
    }

    // Preserve NestJS's default formatting for every other case so the
    // frontend's existing error handling (which already understands
    // `{ message, statusCode, error }`) keeps working.
    if (typeof body === 'string') {
      response.status(status).json({ statusCode: status, message: body });
    } else {
      response.status(status).json(body);
    }
  }
}
