import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { PrismaClient } from '@prisma/client';

/**
 * Soft-delete note (audit M-07):
 *
 * Story, Chapter, and Series all carry a `deletedAt` column. The
 * service layer is responsible for adding `deletedAt: null` to
 * EVERY read query on these models — Prisma 6 removed `$use`
 * middleware, and `$extends` would force a wrapper-shaped service
 * that breaks the existing DI contract. Filtering at the call
 * site is explicit and avoids surprises.
 *
 * The scheduled purge in `cleanup.service.ts` is the only place
 * that intentionally bypasses the filter (via
 * `deletedAt: { not: null }`).
 */
@Injectable()
export class PrismaService
  extends PrismaClient
  implements OnModuleInit, OnModuleDestroy
{
  async onModuleInit() {
    await this.$connect();
  }

  async onModuleDestroy() {
    await this.$disconnect();
  }
}

